using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Threading;
namespace Dafeiyu.Tests
{
    public static class SidebarSectionsTests
    {
        static int passed,failed;static string root;static readonly BindingFlags hidden=BindingFlags.Instance|BindingFlags.NonPublic;
        static void Check(bool ok,string text){if(!ok)throw new Exception(text);}
        static void Run(string name,Action action){try{action();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
        static IEnumerable<T> All<T>(DependencyObject root)where T:DependencyObject{if(root is T)yield return(T)root;foreach(object item in LogicalTreeHelper.GetChildren(root)){var child=item as DependencyObject;if(child!=null)foreach(var x in All<T>(child))yield return x;}}
        static void Pump(){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(60)};timer.Tick+=delegate{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
        static PetSettings Config(){var s=new PetSettings{AgentEnabled=false,ReadReplies=false,GreetingEnabled=false,AutoUpdate=false,OnboardingState="completed"};s.Text.BaseUrl="http://127.0.0.1:1";s.Text.Model="fixture";foreach(var key in s.Hotkeys.Keys.ToArray())s.Hotkeys[key]="";return s;}
        static ProjectSidebar Sidebar(ProjectCatalog c,ProjectCatalogStore store){return new ProjectSidebar(store,c,delegate{},delegate{},delegate{},delegate{},delegate{});}
        [STAThread]public static int Main(){root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"sections-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};
            Run("sidebar supports named sections that persist and projects can move between them",Sections);
            Run("fixed quick group collapses independently",CollapseDefaults);
            Run("selected project has no persistent background or active-only blue dot",NoStickyHighlight);
            Run("running and completed conversations show distinct indicators",Indicators);
            Run("background completion persists unread state and entry clears it",BackgroundCompletion);
            Run("archived conversations are hidden from sidebar and managed in settings",Archive);
            Run("closing quick chat preserves history and reopening starts a fresh conversation",QuickReopen);
            app.Shutdown();Console.WriteLine("Sidebar sections tests: "+passed+" passed, "+failed+" failed");return failed==0?0:1;}
        static void Sections(){var c=ProjectCatalogStore.MigrateLegacy(Config());ProjectCatalogStore.CreateProject(c,"fixture",root);var store=new ProjectCatalogStore(Path.Combine(root,"sections.json"));var sidebar=Sidebar(c,store);Check(!All<TextBlock>(sidebar).Any(t=>t.Text=="聊天")&&All<TextBlock>(sidebar).Any(t=>t.Text=="快速对话"),"fixed quick group missing or obsolete chat section remains");var create=typeof(ProjectSidebar).GetMethod("CreateSection",hidden);var rename=typeof(ProjectSidebar).GetMethod("RenameSection",hidden);var move=typeof(ProjectSidebar).GetMethod("MoveProjectToSection",hidden);Check(create!=null&&rename!=null&&move!=null,"section management missing");var section=create.Invoke(sidebar,new object[]{"研究"});string id=(string)section.GetType().GetField("Id").GetValue(section);rename.Invoke(sidebar,new object[]{id,"资料"});move.Invoke(sidebar,new object[]{c.Projects[0],id});var restored=Sidebar(store.Load(),store);Check(All<TextBlock>(restored).Any(t=>t.Text=="资料")&&All<Button>(restored).Any(b=>b.Name=="WorkspaceProject"),"section rename or membership did not persist");}
        static void CollapseDefaults(){var c=ProjectCatalogStore.MigrateLegacy(Config());var p=ProjectCatalogStore.CreateProject(c,"ordinary",root);var quick=ProjectCatalogStore.CreateConversation(c,ProjectCatalogStore.QuickProjectId,"private");quick.PetId="e-bao";var sidebar=Sidebar(c,new ProjectCatalogStore(Path.Combine(root,"collapse.json")));All<Button>(sidebar).Single(b=>b.Name=="ToggleSection_quick").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(!All<Button>(sidebar).Any(b=>b.Name=="QuickConversation_"+quick.Id),"quick group did not collapse");Check(All<Button>(sidebar).Any(b=>b.Name=="WorkspaceConversation_"+p.Conversations[0].Id),"collapsing quick group changed ordinary project expansion");}
        static void NoStickyHighlight(){var c=ProjectCatalogStore.MigrateLegacy(Config());ProjectCatalogStore.CreateProject(c,"fixture",root);var sidebar=Sidebar(c,new ProjectCatalogStore(Path.Combine(root,"highlight.json")));sidebar.SetActiveConversation(c.Projects[0].Conversations[0].Id);sidebar.Refresh();var button=All<Button>(sidebar).Single(b=>b.Name=="WorkspaceProject");Check(button.Background==Brushes.Transparent || (button.Background is SolidColorBrush&&((SolidColorBrush)button.Background).Color.A==0),"selected project retains a background");Check(!All<Border>(sidebar).Any(b=>b.Name=="ActiveConversationDot"),"selected conversation incorrectly has unread dot");}
        static void Indicators(){var c=new ProjectCatalog();var p=ProjectCatalogStore.CreateProject(c,"indicators",root);var conversation=p.Conversations[0];conversation.Status="running";var sidebar=Sidebar(c,new ProjectCatalogStore(Path.Combine(root,"indicators.json")));Check(All<FrameworkElement>(sidebar).Any(e=>e.Name=="ConversationRunning"),"busy spinner missing");var unread=typeof(ConversationDefinition).GetField("HasUnreadCompletion");Check(unread!=null,"unread state missing");conversation.Status="idle";unread.SetValue(conversation,true);sidebar.Refresh();Check(All<Border>(sidebar).Any(b=>b.Name=="ConversationUnreadDot"),"completed conversation lacks unread dot");}
        static void Archive(){var c=new ProjectCatalog();var p=ProjectCatalogStore.CreateProject(c,"archive",root);p.Conversations[0].Archived=true;var sidebar=Sidebar(c,new ProjectCatalogStore(Path.Combine(root,"archive.json")));Check(!All<Button>(sidebar).Any(b=>b.Name=="ToggleArchived"||b.Name.StartsWith("ArchivedConversation_")||b.Name.StartsWith("ArchivedProject_")),"archived records are managed in settings rather than the sidebar");Check(p.Conversations[0].Archived,"hiding sidebar archive controls preserves archived data");}
        static void BackgroundCompletion(){var cfg=Config();cfg.Text.BaseUrl="http://127.0.0.1";cfg.Text.Model="fixture";cfg.AgentEnabled=false;cfg.ReadReplies=false;var pet=new PetWindow(null,cfg,new SettingsStore(Path.Combine(root,"background","settings.json")),null);var api=new Api();try{
            typeof(PetWindow).GetField("workspaces",hidden).SetValue(pet,new ConversationWorkspaceManager(pet.Store.DirectoryPath,pet.Skin.Id,()=>api,()=>new Silent(),()=>null,()=>cfg,()=>true));var first=ProjectCatalogStore.CreateProject(pet.Projects,"first",root);var second=ProjectCatalogStore.CreateProject(pet.Projects,"second",root);pet.OpenProjectConversation(first,first.Conversations[0]);var workspace=pet.Workspaces.OpenWorkspaces.Single(w=>w.ProjectId==first.Id);workspace.Queue.Enqueue("hold");Pump();Check(first.Conversations[0].Status=="running","actual running request did not publish spinner status");pet.OpenProjectConversation(second,second.Conversations[0]);api.Held.SetResult("completed in background");for(int i=0;i<15;i++)Pump();Check(first.Conversations[0].HasUnreadCompletion&&first.Conversations[0].Status=="idle","background completion did not mark unread");Check(pet.ProjectStore.Load().Projects.Single(p=>p.Id==first.Id).Conversations[0].HasUnreadCompletion,"unread completion was not persisted");pet.OpenProjectConversation(first,first.Conversations[0]);Pump();Check(!first.Conversations[0].HasUnreadCompletion,"entering completed chat did not clear unread");
        }finally{foreach(var chat in Application.Current.Windows.OfType<ChatWindow>().ToArray())chat.Close();pet.Close();Pump();}}
        static void QuickReopen(){var cfg=Config();var pet=new PetWindow(null,cfg,new SettingsStore(Path.Combine(root,"quick-data","settings.json")),null);try{
            var manager=new ConversationWorkspaceManager(pet.Store.DirectoryPath,pet.Skin.Id,()=>new Api(),()=>new Silent(),()=>null,()=>cfg,()=>true);typeof(PetWindow).GetField("workspaces",hidden).SetValue(pet,manager);
            pet.Show();pet.ShowQuickChat();Pump();var quick=Application.Current.Windows.OfType<QuickChatWindow>().Single();var previous=pet.Workspaces.OpenWorkspaces.Single();string oldId=previous.Id,oldDirectory=previous.DataDirectory;var session=(ConversationSession)typeof(QuickChatWindow).GetField("session",hidden).GetValue(quick);All<MarkdownEditor>(quick).Single(t=>t.Name=="QuickMessageInput").Text="old unsent draft";session.AddLiveTurn(pet.Skin.Id,"quick history","reply");session.FlushHistoryAsync().GetAwaiter().GetResult();Check(String.IsNullOrEmpty(session.HistoryWarning),"quick history did not save: "+session.HistoryWarning);Check(session.History.Messages.Count>0,"quick fixture did not create history for active persona "+session.PersonaId+"/"+pet.Skin.Id);quick.Close();Pump();pet.ShowQuickChat();Pump();var next=Application.Current.Windows.OfType<QuickChatWindow>().Single();var nextSession=(ConversationSession)typeof(QuickChatWindow).GetField("session",hidden).GetValue(next);Check(pet.Projects.QuickConversations.Count==2&&!pet.Projects.Projects.Any(),"reopened quick chat must create a separate record in its fixed group");Check(nextSession.History.Messages.Count==0 && All<MarkdownEditor>(next).Single(t=>t.Name=="QuickMessageInput").Text=="","reopened quick chat inherited old history or draft");Check(pet.Projects.QuickConversations.Any(c=>c.Id==oldId)&&new HistoryStore(Path.Combine(oldDirectory,"history")).Load(pet.Skin.Id).Any(m=>m.Content=="quick history"),"previous conversation must remain available on disk and in the catalog");pet.ShowQuickChat();Pump();Check(ReferenceEquals(next,Application.Current.Windows.OfType<QuickChatWindow>().Single())&&pet.Projects.QuickConversations.Count==2,"activating an already open quick chat must not create another record");next.Close();Pump();
        }finally{pet.Close();Pump();}}
        sealed class Api:IConversationApi{internal readonly TaskCompletionSource<string> Held=new TaskCompletionSource<string>();public Task<string> ChatAsync(ConnectionSettings s,IList<ChatMessage> m,CancellationToken t){if(m.Last().Content=="hold")return Held.Task;return Task.FromResult("reply");}public Task<string> TranscribeAsync(ConnectionSettings s,byte[] b,CancellationToken t){return Task.FromResult("");}public Task<byte[]> SpeechAsync(ConnectionSettings s,string v,string text,CancellationToken t){return Task.FromResult(new byte[0]);}public void Dispose(){}}
        sealed class Silent:IReplySpeech{public Task SpeakAsync(string s,PetSettings p,CancellationToken t){return Task.FromResult(0);}public void Stop(){}public void SetVolume(int n){}public void Dispose(){}}
    }
}
